function name(key){const s=String(f[key]??'').trim();if(!/^[\p{L}\p{N}_ .()-]+\.md$/iu.test(s)||s.startsWith('.')||s.includes('..')||s.length>240)throw new Error('Nom Markdown invalide : '+key);return s;}
const base='/home/daniel/projets-agentiques/Atelier-Agentique-Editorial/data';
const source=name('Fichier Source Brute (.md)'), manuscript=name('Votre Manuscrit Rédigé (.md)'), context=name('Dossier de travail (.md)');
const id=String($execution.id);if(!/^[A-Za-z0-9_-]+$/.test(id))throw new Error('Identifiant invalide');
return [{json:{source,manuscript,context,sourcePath:base+'/03_transcriptions/'+source,manuscriptPath:base+'/05_manuscrits/'+manuscript,contextPath:base+'/04_mandats/'+context,output:base+'/06_audits/RAPPORT_AUDIT_'+id+'.md',id}}];

