const b=await this.helpers.getBinaryDataBuffer(0,'data');
const text=b.toString('utf8').replace(/^\uFEFF/,'');
if(!text.trim()||text.includes('\uFFFD')||text.includes('\u0000'))throw new Error('Fichier vide ou texte UTF-8 invalide');
if(text.length>1000000)throw new Error('Fichier trop long pour le contrat Dify');
