return [{json:{reference_context:text}}];

const f=$('Valider fichiers').first().json;
const source_text=$('Décoder Source').first().json.source_text;
const revised_text=$('Décoder Manuscrit').first().json.revised_text;
let reference_context=$('Décoder Contexte').first().json.reference_context;
// Format exporté par Studio Editorial : retirer uniquement la transcription redondante en fin de dossier.
const marker='\n\n## Transcription normalisée\n\n';const idx=reference_context.lastIndexOf(marker);
if(idx>=0)reference_context=reference_context.slice(0,idx);
const match=reference_context.match(/^Source : (.+)$/m);
if(match&&match[1].trim()!==f.source)throw new Error('Le dossier de travail ne correspond pas à la source sélectionnée');
return [{json:{source_text,revised_text,reference_context}}];

const response=$input.first().json;
const d=response.data;
if(d?.status!=='succeeded')throw new Error('Atelier 4 : '+(d?.error||'exécution non réussie'));
const o=d.outputs;
for(const k of ['rapport_comparatif','audit_coherence_finale'])if(typeof o?.[k]!=='string'||!o[k].trim())throw new Error('Sortie Dify absente : '+k);
const f=$('Valider fichiers').first().json;
const markdown=['# Rapport d’audit de finition','Audit : '+f.id,'Date : '+new Date().toISOString(),'Source : '+f.source,'Manuscrit : '+f.manuscript,'Dossier de travail : '+f.context,'Exécution Dify : '+(response.workflow_run_id||d.id||'non renseignée'),'## Rapport comparatif',o.rapport_comparatif,'---','## Audit de cohérence finale',o.audit_coherence_finale].join('\n\n');
const data=await this.helpers.prepareBinaryData(Buffer.from(markdown,'utf8'),f.output.split('/').pop(),'text/markdown');
return [{json:{output:f.output},binary:{data}}];
